    }

    /* 9. Randomness kept in state. Seeded per sim and per game (per page load where there is no game id),
       so a new session still gets new draws; the generator's position is stored in domainState after every
       call, and an undo restores the domainState it had, so the same round replays the same draws. */
    var pageSeed = Math.floor(Math.random() * 4294967296), seedBase = null;
    function seeded(state, tag, fn) {
        var ds = state && state.domainState, s0;
        // the base is fixed on first use for the life of the page: the boot-time initialise can run before
        // the game id is known, and an undo of round 1 must start from the same place as the first play did
        if (seedBase === null) { seedBase = state && state.gameId ? String(state.gameId) : String(pageSeed); }
        // one stream for initialise and scoring: a path that rebuilds domainState without the stored
        // position (the undo of round 1 does, in some sims) then restarts where the first play started
        if (ds && typeof ds.__eqilRng === "number") { s0 = ds.__eqilRng; }
        else { s0 = hash(SEED + "|" + seedBase + "|rng"); }
        var a = s0 | 0, own = Math.random;
        Math.random = function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
        try { return fn(); }
        finally {
            Math.random = own;
            // only into a domainState the adapter has filled: adapters that test "is domainState empty?"
            // to decide whether to initialise must still see it empty
            try {
                var d2 = state && state.domainState, any = false;
                if (d2 && typeof d2 === "object") { for (var dk in d2) { if (dk !== "__eqilRng" && Object.prototype.hasOwnProperty.call(d2, dk)) { any = true; break; } } }
                if (any) { d2.__eqilRng = a; }
            } catch (e) {}
        }
    }

    /* 10. A complete run has no live submit button. */
    var SUBMIT_IDS = ["nextPeriodBtn", "submitDecisionBtn", "submitBtn", "submitPeriodBtn", "sendDecisionBtn", "roundSubmitBtn", "enviarBtn", "decisionBtn"];
    function closeRun() {
        var f = sim(), done = false, i, b;
        if (!f || !f.state) { return; }
        try { done = typeof f.isRunComplete === "function" ? !!f.isRunComplete() : !!(f._finished || Number(f.state.currentPeriod) > Number(f.state.maxPeriods)); } catch (e) { return; }
        for (i = 0; i < SUBMIT_IDS.length; i++) {
            b = document.getElementById(SUBMIT_IDS[i]);
            if (!b) { continue; }
            if (done && !b.disabled) { b.disabled = true; b.setAttribute("aria-disabled", "true"); b.__eqilClosed = true; }
            else if (!done && b.__eqilClosed) { b.disabled = false; b.removeAttribute("aria-disabled"); b.__eqilClosed = false; }
        }
    }

    function doSelect(sel, roundChanged) {
        var opts = sel.options, real = [], ph = null, fresh = false, i;
        for (i = 0; i < opts.length; i++) {
            if (isPlaceholder(opts[i])) { if (!ph) { ph = opts[i]; } continue; }
            real.push(opts[i]);
            if (!opts[i].__eqil) { fresh = true; }
        }
        if (real.length < 2) { return; }
        sel.__eqilManaged = true;
        var none = ph ? ph.value : "";
        if (fresh) {
            var before = sel.value, prev = sel.__eqilLast, wasUser = sel.__eqilUser && !roundChanged;
            if (!ph && MODE !== "blank") {
                ph = document.createElement("option");
                ph.value = "";
                ph.disabled = true;
                ph.setAttribute("data-eqil-ph", "1");
                sel.insertBefore(ph, sel.firstChild);
            }
            var texts = [], values = [];
            for (i = 0; i < real.length; i++) { real[i].__eqil = true; texts.push(real[i].textContent); values.push(real[i].value); }
            if (MODE !== "blank" && !sel.querySelector("optgroup") && !ordinal(texts, values)) {
                var order = permute(real, gameKey(sel.id || sel.name || "", values));
                for (i = 0; i < order.length; i++) { sel.appendChild(order[i]); }
            }
            sel.__eqilDef = before;
            sel.__eqilPh = ph ? ph.value : "";
            if (wasUser && prev && prev !== sel.__eqilPh && hasValue(sel, prev)) { sel.value = prev; }
            else if (shown(sel)) { clear(sel, ph); sel.__eqilUser = false; }
