        // Capture the mutable scalar domain state before a round is applied (v1.1.0); plain data.
        _snapshot(ds) {
            return {
                cashReserves: ds.cashReserves,
                loanPortfolio: ds.loanPortfolio,
                nplRatio: ds.nplRatio,
                efficiencyRatio: ds.efficiencyRatio,
                memberCount: ds.memberCount,
                memberSatisfaction: ds.memberSatisfaction,
                capitalAdequacy: ds.capitalAdequacy,
                financialHealth: ds.financialHealth,
                socialImpact: ds.socialImpact,
                coopScore: ds.coopScore,
                lastEvent: ds.lastEvent
            };
        }

        // Restore a per-round checkpoint and truncate the 3 history arrays to (period-1) (v1.1.0).
        _restore(ds, snap, period) {
            ds.cashReserves = snap.cashReserves;
            ds.loanPortfolio = snap.loanPortfolio;
            ds.nplRatio = snap.nplRatio;
            ds.efficiencyRatio = snap.efficiencyRatio;
            ds.memberCount = snap.memberCount;
            ds.memberSatisfaction = snap.memberSatisfaction;
            ds.capitalAdequacy = snap.capitalAdequacy;
            ds.financialHealth = snap.financialHealth;
            ds.socialImpact = snap.socialImpact;
            ds.coopScore = snap.coopScore;
            ds.lastEvent = snap.lastEvent;
            var keep = period - 1;
            if (ds.financialHealthHistory.length > keep) ds.financialHealthHistory.length = keep;
            if (ds.socialImpactHistory.length > keep) ds.socialImpactHistory.length = keep;
            if (ds.coopScoreHistory.length > keep) ds.coopScoreHistory.length = keep;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = t(round.titleKey);

            var descEl = document.getElementById('briefingText');
            if (descEl) descEl.innerHTML = t(round.descKey);

            var inp1 = document.getElementById('numericInput1');
            var lbl1 = document.getElementById('label1');
            var hnt1 = document.getElementById('hint1');
            if (inp1) { inp1.min = round.input1.min; inp1.max = round.input1.max; inp1.value = round.input1.value; }
            if (lbl1) lbl1.innerHTML = t(round.input1.labelKey);
            if (hnt1) hnt1.innerHTML = t(round.input1.hintKey);

            var inp2 = document.getElementById('numericInput2');
            var lbl2 = document.getElementById('label2');
            var hnt2 = document.getElementById('hint2');
            if (inp2) { inp2.min = round.input2.min; inp2.max = round.input2.max; inp2.value = round.input2.value; }
            if (lbl2) lbl2.innerHTML = t(round.input2.labelKey);
            if (hnt2) hnt2.innerHTML = t(round.input2.hintKey);

            var sel = document.getElementById('strategySelect');
            var lbl3 = document.getElementById('label3');
            var hnt3 = document.getElementById('hint3');
            if (lbl3) lbl3.innerHTML = t(round.select.labelKey);
            if (hnt3) hnt3.innerHTML = t(round.select.hintKey);
            if (sel) {
                sel.innerHTML = '';
                for (var i = 0; i < round.select.options.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.select.options[i].value;
                    opt.textContent = t(round.select.options[i].labelKey);
                    sel.appendChild(opt);
                }
            }

            var eventAlert = document.getElementById('eventAlert');
            if (eventAlert) eventAlert.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CoopLeaderAdapter(), {
            simulationType: 'coopleader_credit_union',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
